package com.bank.aqeopt.rules;

import com.bank.aqeopt.model.ShufflePartition;
import java.util.*;
import java.util.logging.Logger;

// (1) Post-shuffle coalescing: merge small partitions toward a target size.
public class CoalesceRule {
    private static final Logger log = Logger.getLogger(CoalesceRule.class.getName());
    private final long targetBytes;

    public CoalesceRule(long targetBytes) { this.targetBytes = targetBytes; }

    public List<ShufflePartition> apply(List<ShufflePartition> parts) {
        List<ShufflePartition> out = new ArrayList<>();
        long acc = 0; List<String> merged = new ArrayList<>();
        for (ShufflePartition p : parts) {
            acc += p.getBytes();
            merged.add(p.getKey());
            if (acc >= targetBytes) {              // flush a coalesced group
                out.add(new ShufflePartition(String.join("+", merged), acc));
                acc = 0; merged = new ArrayList<>();
            }
        }
        if (!merged.isEmpty()) out.add(new ShufflePartition(String.join("+", merged), acc));
        log.info(() -> "AQE coalesce: " + parts.size() + " partitions => " + out.size());
        return out;
    }
}
