package com.bank.aqeopt.rules;

import com.bank.aqeopt.model.ShufflePartition;
import java.util.*;
import java.util.logging.Logger;

// (2) Skew handling: split any partition that is both >factor*median AND >threshold.
public class SkewRule {
    private static final Logger log = Logger.getLogger(SkewRule.class.getName());
    private final int factor;
    private final long thresholdBytes;

    public SkewRule(int factor, long thresholdBytes) {
        this.factor = factor;
        this.thresholdBytes = thresholdBytes;
    }

    public List<ShufflePartition> apply(List<ShufflePartition> parts) {
        long median = median(parts);
        List<ShufflePartition> out = new ArrayList<>();
        for (ShufflePartition p : parts) {
            if (p.getBytes() > (long) factor * median && p.getBytes() > thresholdBytes) {
                int splits = (int) Math.ceil((double) p.getBytes() / thresholdBytes);
                long each = p.getBytes() / splits;
                log.warning(() -> "AQE skew: '" + p.getKey() + "' (" + p.getBytes()
                        + "B) split into " + splits + " sub-partitions");
                for (int i = 0; i < splits; i++) {
                    out.add(new ShufflePartition(p.getKey() + "#sub" + i, each));
                }
            } else {
                out.add(p);
            }
        }
        return out;
    }

    private long median(List<ShufflePartition> parts) {
        List<Long> sizes = new ArrayList<>();
        for (ShufflePartition p : parts) sizes.add(p.getBytes());
        Collections.sort(sizes);
        return sizes.get(sizes.size() / 2);
    }
}
