package com.bank.aqeopt.rules;

import java.util.logging.Logger;

// (3) Dynamic join switch: shuffle join -> broadcast join if a side is small.
public class JoinSwitchRule {
    private static final Logger log = Logger.getLogger(JoinSwitchRule.class.getName());
    private final long broadcastLimit;

    public JoinSwitchRule(long broadcastLimit) { this.broadcastLimit = broadcastLimit; }

    public String apply(String plannedStrategy, long actualSmallSideBytes) {
        if ("SORT_MERGE".equals(plannedStrategy) && actualSmallSideBytes <= broadcastLimit) {
            log.info(() -> "AQE join switch: side " + actualSmallSideBytes
                    + "B <= limit => SORT_MERGE to BROADCAST (shuffle avoided)");
            return "BROADCAST";
        }
        log.info(() -> "AQE join: keep " + plannedStrategy
                + " (side " + actualSmallSideBytes + "B exceeds broadcast limit)");
        return plannedStrategy;
    }
}
