package com.bank.aqeopt;

import com.bank.aqeopt.model.ShufflePartition;
import com.bank.aqeopt.rules.*;
import java.util.*;
import java.util.logging.*;

public class AqeOptDemo {
    private static final Logger log = Logger.getLogger(AqeOptDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new AqeOptLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // Realistic post-shuffle sizes: many tiny, one skewed (month-end branch).
        List<ShufflePartition> parts = new ArrayList<>(List.of(
            new ShufflePartition("MUM", 10_000_000),
            new ShufflePartition("DEL", 12_000_000),
            new ShufflePartition("BLR", 9_000_000),
            new ShufflePartition("CHE", 11_000_000),
            new ShufflePartition("HYD", 400_000_000)  // skewed
        ));

        // (1) coalesce toward 64 MB
        var coalesced = new CoalesceRule(64_000_000).apply(parts);
        // (2) skew: >5x median AND >256MB
        var deskewed = new SkewRule(5, 256_000_000).apply(coalesced);
        log.info(() -> "partitions after coalesce+skew = " + deskewed.size());

        // (3) dynamic join switch: dimension table is 8MB after filter
        String strategy = new JoinSwitchRule(10_485_760)
                .apply("SORT_MERGE", 8_000_000);
        log.info(() -> "final join strategy = " + strategy);
    }
}

